const opciones = [];
let intentoDia = 1;

// Función auxiliar para formato ISO local con offset (-03:00)
function toLocalISO(date) {
  const pad = (n) => String(n).padStart(2, '0');
  const year = date.getFullYear();
  const month = pad(date.getMonth() + 1);
  const day = pad(date.getDate());
  const hours = pad(date.getHours());
  const minutes = pad(date.getMinutes());
  const seconds = pad(date.getSeconds());
  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}-03:00`;
}

while (opciones.length < 5 && intentoDia <= 10) {
  const fecha = new Date();
  fecha.setDate(fecha.getDate() + intentoDia);

  const diaSemana = fecha.getDay();

  if (diaSemana !== 0 && diaSemana !== 6) {
    const hora = Math.floor(Math.random() * (17 - 9 + 1)) + 9;

    const fechaInicio = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), hora, 0, 0);
    const fechaFin = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), hora + 1, 0, 0);

    const fechaTexto = fechaInicio.toLocaleString('es-AR', {
      timeZone: 'America/Argentina/Buenos_Aires',
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });

    opciones.push({
      numero_opcion: opciones.length + 1,
      fecha_presentada: fechaTexto,
      start_time: toLocalISO(fechaInicio),
      end_time: toLocalISO(fechaFin)
    });
  }
  intentoDia++;
}

return JSON.stringify(opciones);
